try:
    class Tr:
        def __init__(s, n): s.n = n
        def _b(op):
            def m(s, o): log.append("%s.%s" % (s.n, op)); return s
            return m
        for _op in ("add", "radd", "sub", "mul", "truediv", "floordiv", "mod", "pow", "lshift", "rshift", "and", "or", "xor", "matmul", "lt", "le", "gt", "ge", "eq", "ne", "iadd", "getitem", "contains"):
            locals()["__%s__" % _op] = _b(_op)
        __hash__ = None
        def __neg__(s): log.append(s.n + ".neg"); return s
        def __invert__(s): log.append(s.n + ".invert"); return s
        def __bool__(s): log.append(s.n + ".bool"); return True
        def __call__(s, *a, **k): log.append(s.n + ".call"); return s
        def __getattr__(s, a):
            if a.startswith("__"): raise AttributeError(a)
            log.append("%s.getattr(%s)" % (s.n, a)); return s
        def __setitem__(s, k, v): log.append(s.n + ".setitem")
        def __delitem__(s, k): log.append(s.n + ".delitem")
        def __repr__(s): return "Tr(%s)" % s.n
except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + '> in: class Tr:')
